wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input in the shared store (author-granted state-rw).
        state_rw::put("last-input", &feed_url);

        // Read the clock.
        let seconds = wall_clock::now().seconds;

        // One permitted fetch. A transport failure is data, not a failure of
        // the heartbeat: it is reported as zero characters fetched. A URL
        // outside the handle's allowlist traps at the boundary.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notify. The contract requires `notified == true` on every output,
        // so a refused notification is retried once, and if still refused the
        // node traps rather than emitting an output that violates `ensures`.
        let message = format!(
            "heartbeat at {seconds}: fetched {fetched} characters from {feed_url}"
        );
        let mut notified = notifier::notify(&message);
        if !notified {
            notified = notifier::notify(&message);
        }
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
